import React, { useState, useEffect } from 'react';
import { dashboardAPI, devAPI } from '../services/api';
import { useWebSocket } from '../hooks/useWebSocket';
import { 
  Zap, Activity, TrendingUp, AlertTriangle, 
  DollarSign, Battery, Wifi, WifiOff, RefreshCw
} from 'lucide-react';
import { toast } from 'react-toastify';
import RealtimeCharts from '../components/RealtimeCharts';
import { formatRupiah, formatKWh } from '../utils/format';

const StatCard = ({ title, value, unit, icon: Icon, color, trend, status }) => {
  const colorMap = {
    blue: 'from-blue-600 to-blue-500',
    cyan: 'from-cyan-600 to-cyan-500',
    green: 'from-emerald-600 to-emerald-500',
    amber: 'from-amber-600 to-amber-500',
    red: 'from-red-600 to-red-500',
    purple: 'from-purple-600 to-purple-500',
  };

  const statusColor = {
    normal: 'text-emerald-400',
    high: 'text-red-400',
    low: 'text-amber-400',
    warning: 'text-amber-400',
  };

  return (
    <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-5 hover:border-blue-500/30 transition-all duration-300 group">
      <div className="flex items-start justify-between mb-4">
        <div className={`w-11 h-11 rounded-xl bg-gradient-to-br ${colorMap[color] || colorMap.blue} flex items-center justify-center shadow-lg`}>
          <Icon className="w-5 h-5 text-white" />
        </div>
        {status && (
          <span className={`text-xs font-semibold uppercase tracking-wide px-2 py-1 rounded-lg bg-slate-800 ${statusColor[status] || 'text-slate-400'}`}>
            {status}
          </span>
        )}
      </div>
      <div>
        <p className="text-slate-400 text-sm mb-1">{title}</p>
        <div className="flex items-baseline gap-1.5">
          <span className="text-2xl font-bold text-white font-mono">{value}</span>
          <span className="text-slate-400 text-sm">{unit}</span>
        </div>
        {trend && <p className="text-xs text-slate-500 mt-1">{trend}</p>}
      </div>
    </div>
  );
};

const CostProgressBar = ({ current, max, percentage }) => (
  <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-5">
    <div className="flex items-center justify-between mb-4">
      <div className="flex items-center gap-3">
        <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-blue-600 to-cyan-500 flex items-center justify-center">
          <DollarSign className="w-5 h-5 text-white" />
        </div>
        <div>
          <p className="text-slate-400 text-sm">Biaya Bulan Ini</p>
          <p className="text-xl font-bold text-white font-mono">{formatRupiah(current)}</p>
        </div>
      </div>
      <div className="text-right">
        <p className="text-xs text-slate-500">Batas</p>
        <p className="text-sm font-semibold text-slate-300">{formatRupiah(max)}</p>
      </div>
    </div>

    <div className="w-full h-3 bg-slate-800 rounded-full overflow-hidden">
      <div
        className={`h-full rounded-full transition-all duration-1000 ${
          percentage >= 100 ? 'bg-red-500' :
          percentage >= 80 ? 'bg-amber-500' :
          'bg-gradient-to-r from-blue-600 to-cyan-400'
        }`}
        style={{ width: `${Math.min(percentage, 100)}%` }}
      />
    </div>
    <div className="flex justify-between mt-2">
      <span className="text-xs text-slate-500">{percentage.toFixed(1)}% terpakai</span>
      <span className={`text-xs font-medium ${
        percentage >= 100 ? 'text-red-400' :
        percentage >= 80 ? 'text-amber-400' : 'text-emerald-400'
      }`}>
        {percentage >= 100 ? '⚠ Melebihi Batas' :
         percentage >= 80 ? '⚠ Mendekati Batas' : '✓ Aman'}
      </span>
    </div>
  </div>
);

const DashboardPage = () => {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const { isConnected, lastData } = useWebSocket();

  const fetchSummary = async () => {
    try {
      const response = await dashboardAPI.getSummary();
      setSummary(response.data);
    } catch (err) {
      toast.error('Gagal memuat data dashboard');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSummary();
    const interval = setInterval(fetchSummary, 10000);
    return () => clearInterval(interval);
  }, []);

  // Update with WebSocket data
  useEffect(() => {
    if (lastData && summary) {
      setSummary(prev => ({
        ...prev,
        tegangan_terkini: lastData.tegangan,
        arus_terkini: lastData.arus,
        daya_terkini: lastData.daya,
      }));
    }
  }, [lastData]);

  const generateSampleData = async () => {
    try {
      toast.info('Generating sample data...');
      await devAPI.generateSampleData();
      toast.success('Sample data berhasil dibuat!');
      fetchSummary();
    } catch {
      toast.error('Gagal generate sample data');
    }
  };

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <div className="text-center">
        <div className="w-12 h-12 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto mb-3" />
        <p className="text-slate-400">Memuat dashboard...</p>
      </div>
    </div>
  );

  const data = summary || {};

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-display font-bold text-white">Dashboard</h1>
          <p className="text-slate-400 text-sm mt-0.5">Pemantauan energi listrik realtime</p>
        </div>
        <div className="flex items-center gap-3">
          <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium border ${
            isConnected 
              ? 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400'
              : 'border-slate-600/30 bg-slate-800/40 text-slate-400'
          }`}>
            {isConnected ? <Wifi className="w-3 h-3" /> : <WifiOff className="w-3 h-3" />}
            {isConnected ? 'Live' : 'Offline'}
          </div>
          <button
            onClick={generateSampleData}
            className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-800 border border-slate-700 text-slate-300 hover:bg-slate-700 text-xs transition-colors"
          >
            <RefreshCw className="w-3.5 h-3.5" />
            Generate Test Data
          </button>
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          title="Tegangan"
          value={(data.tegangan_terkini || 0).toFixed(1)}
          unit="V"
          icon={Zap}
          color="blue"
          status={data.status_tegangan}
          trend={`Min: 190V | Max: 250V`}
        />
        <StatCard
          title="Arus"
          value={(data.arus_terkini || 0).toFixed(2)}
          unit="A"
          icon={Activity}
          color="cyan"
          status={data.status_arus}
          trend={`Batas: ${data.current_max || 20}A`}
        />
        <StatCard
          title="Daya Aktif"
          value={(data.daya_terkini || 0).toFixed(0)}
          unit="W"
          icon={TrendingUp}
          color="purple"
          trend="Konsumsi saat ini"
        />
        <StatCard
          title="Energi Hari Ini"
          value={formatKWh(data.energi_hari_ini || 0)}
          unit="kWh"
          icon={Battery}
          color="green"
          trend={`≈ ${formatRupiah(data.biaya_hari_ini || 0)}`}
        />
      </div>

      {/* Cost Progress + Alerts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        <CostProgressBar
          current={data.biaya_bulan_ini || 0}
          max={data.batas_biaya_bulanan || 500000}
          percentage={data.persentase_biaya || 0}
        />
        <div className="bg-slate-900/60 border border-slate-700/40 rounded-2xl p-5">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-11 h-11 rounded-xl bg-gradient-to-br from-amber-600 to-amber-500 flex items-center justify-center">
              <AlertTriangle className="w-5 h-5 text-white" />
            </div>
            <div>
              <p className="text-slate-400 text-sm">Peringatan Belum Dibaca</p>
              <p className="text-2xl font-bold text-white font-mono">{data.total_alert_unread || 0}</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div className="bg-slate-800/50 rounded-xl p-3 text-center">
              <p className="text-xs text-slate-500 mb-1">Energi Bulan Ini</p>
              <p className="text-white font-bold font-mono">{formatKWh(data.energi_bulan_ini || 0)}</p>
              <p className="text-slate-500 text-xs">kWh</p>
            </div>
            <div className="bg-slate-800/50 rounded-xl p-3 text-center">
              <p className="text-xs text-slate-500 mb-1">Tarif/kWh</p>
              <p className="text-white font-bold font-mono">{formatRupiah(data.harga_per_kwh || 0)}</p>
              <p className="text-slate-500 text-xs">per kWh</p>
            </div>
          </div>
        </div>
      </div>

      {/* Realtime Charts */}
      <RealtimeCharts />
    </div>
  );
};

export default DashboardPage;
